contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _to, uint256 _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_to != address(0), "recipient must not be zero address");
        require(address(this).balance >= 0);

        uint256 senderBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBalanceBefore = c.balanceOf(_to); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool success;
        bool s = c.transfer(_to, _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            success = false;
        } else {
            reverted = false;
            success = s;
        }

        uint256 senderBalanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipientBalanceAfter = c.balanceOf(_to); if (__ESBMC_reverted()) return;
        uint256 totalSupplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            (
                success == true &&
                senderBalanceAfter == senderBalanceBefore - _value &&
                recipientBalanceAfter == recipientBalanceBefore + _value &&
                totalSupplyAfter == totalSupplyBefore
            )
        );
    }
}

