// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address _to, uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_to != address(0));
        vm.assume(address(this).balance >= 0);
        uint256 senderBalanceBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { senderBalanceBefore = __r; } catch { return; }
        uint256 recipientBalanceBefore;
        try c.balanceOf(_to) returns (uint256 __r) { recipientBalanceBefore = __r; } catch { return; }
        uint256 totalSupplyBefore;
        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        bool reverted;
        bool success;
        try c.transfer(_to, _value) returns (bool s) {
            reverted = false;
            success = s;
        } catch {
            reverted = true;
            success = false;
        }
        uint256 senderBalanceAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { senderBalanceAfter = __r; } catch { return; }
        uint256 recipientBalanceAfter;
        try c.balanceOf(_to) returns (uint256 __r) { recipientBalanceAfter = __r; } catch { return; }
        uint256 totalSupplyAfter;
        try c.totalSupply() returns (uint256 __r) { totalSupplyAfter = __r; } catch { return; }
        assertTrue(reverted ||
            (
                success == true &&
                senderBalanceAfter == senderBalanceBefore - _value &&
                recipientBalanceAfter == recipientBalanceBefore + _value &&
                totalSupplyAfter == totalSupplyBefore
            ));
    }

    function testFuzz_run(address _to, uint256 _value) public {
        vm.assume(_to.code.length == 0 && uint160(_to) > 0xffff && _to != address(this) && _to != address(c) && _to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _to != 0x000000000000000000636F6e736F6c652e6c6f67 && _to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_to, _value);
    }

    receive() external payable {}
}
